function bytesToHexColors(bytes, n = 3) {
  const palette = [];
  const len = bytes.length;
  for (let i = 0; i < n; i++) {
    const o = Math.floor((i + 0.5) * len / n);
    const r = bytes[o % len], g = bytes[(o + Math.floor(len / 7) + 1) % len], b = bytes[(o + Math.floor(len / 3) + 2) % len];
    palette.push('#' + [r, g, b].map((v) => (v | 0).toString(16).padStart(2, '0')).join(''));
  }
  return palette;
}

function pngDimensions(bytes) {
  // PNG: 8-byte signature, then IHDR chunk: len(4) 'IHDR' width(4) height(4)
  if (bytes.length < 24) return null;
  const sig = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  for (let i = 0; i < 8; i++) if (bytes[i] !== sig[i]) return null;
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const w = dv.getUint32(16), h = dv.getUint32(20);
  if (w > 0 && h > 0 && w < 100000 && h < 100000) return { width: w, height: h };
  return null;
}

