function loadPlayerSeed(eventStream) {
  const events = eventStream.events();
  const created = events.find((e) => e.type === 'PLAYER_SEED_CREATED');
  if (!created) return null;
  const seed = JSON.parse(JSON.stringify(created.data.seed));
  for (const e of events) {
    if (e.id === created.id) continue;
    if (e.type === 'PLAYER_HISTORY_ADDED' && e.data.playerId === seed.playerId) {
      const { kind, entry } = e.data;
      if (seed.history[kind] && !seed.history[kind].some((x) => x.id === entry.id)) seed.history[kind].push(entry);
    } else if (e.type === 'PLAYER_METAPHYSICAL_UPDATED' && e.data.playerId === seed.playerId) {
      seed.metaphysicalState = { ...seed.metaphysicalState, ...e.data.patch };
    } else if (e.type === 'PLAYER_EMBODIMENT_SET' && e.data.playerId === seed.playerId) {
      seed.currentEmbodiment = e.data.morphId;
    } else if (e.type === 'PLAYER_WORLD_SET' && e.data.playerId === seed.playerId) {
      seed.currentWorld = e.data.worldId;
    } else if (e.type === 'PLAYER_PROGRESSION' && e.data.playerId === seed.playerId) {
      seed.progression = { ...seed.progression, ...e.data.patch };
    }
  }
  return seed;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function fnv1a(bytes) {
