function measureInput(input) {
    const letters = (input.match(/[a-zA-Z]/g) || []).length;
    const words = input.trim().split(/\s+/).filter(Boolean).length;
    const avgWordLength = words > 0 ? letters / words : 0;
    const punctuation = (input.match(/[.,;:!?\-]/g) || []).length;
    const chonps = { C: 0, H: 0, O: 0, N: 0, P: 0, S: 0 };
    const upper = input.toUpperCase();
    for (const char of upper) {
        if (chonps[char] !== undefined)
            chonps[char]++;
