function textToCodons(text) {
    const nucleotides = [];
    for (const char of text.toUpperCase()) {
        const code = char.charCodeAt(0);
        if (code >= 65 && code <= 90) {
            const idx = code - 65;
            if (idx < 6)
                nucleotides.push('A');
            else if (idx < 12)
                nucleotides.push('T');
            else if (idx < 18)
                nucleotides.push('G');
            else
                nucleotides.push('C');
        }
    }
    const codons = [];
    for (let i = 0; i < nucleotides.length - 2; i += 3) {
        codons.push(nucleotides[i] + nucleotides[i + 1] + nucleotides[i + 2]);
    }
    while (codons.length < 9) {
        codons.push(['ATG', 'CGT', 'AAG', 'TGG', 'GAC'][codons.length % 5]);
    }
    return codons.slice(0, 9);
}

function determineDimension(chonps, gateNum, avgWordLength) {
    const total = Object.values(chonps).reduce((a, b) => a + b, 0);
    if (total === 0) {
        const dims = ['MOVEMENT', 'EVOLUTION', 'BEING', 'DESIGN', 'SPACE'];
        return dims[gateNum % 5];
    }
    const scores = {
        MOVEMENT: chonps.O * 1.2 + chonps.H * 0.8,
        EVOLUTION: chonps.N * 1.3 + chonps.C * 0.7,
        BEING: chonps.S * 1.2 + chonps.C * 0.9 + avgWordLength * 0.5,
        DESIGN: chonps.P * 1.3 + chonps.C * 0.6,
        SPACE: chonps.H * 1.1 + (chonps.O + chonps.N) * 0.3,
    };
    let best = 'SPACE';
    let bestScore = -Infinity;
    for (const [dim, score] of Object.entries(scores)) {
        if (score > bestScore) {
            bestScore = score;
            best = dim;
        }
    }
    return best;
}

function deriveGateLine(measurements) {
    const { letters, words, punctuation, avgWordLength } = measurements;
    const composite = (letters * 0.5 + words * 2 + punctuation * 3 + avgWordLength * 4);
    const gate = (Math.floor(composite) % 64) + 1;
    const line = (Math.floor(composite * 7.3) % 6) + 1;
    const color = (Math.floor(composite * 11.7) % 6) + 1;
    const tone = (Math.floor(composite * 13.1) % 6) + 1;
    const base = (Math.floor(composite * 5.9) % 5) + 1;
    const degree = Math.floor((composite % 1) * 30);
    const minute = Math.floor(((composite * 60) % 1) * 60);
    const second = Math.floor(((composite * 3600) % 1) * 60);
    return { gate, line, color, tone, base, degree, minute, second };
}

