function birthDateFromInput(input) {
    const [year, month, day] = input.date.split('-').map(Number);
    const [hour, minute] = input.time.split(':').map(Number);
    if (!year || !month || !day || !Number.isFinite(hour) || !Number.isFinite(minute))
        throw new Error('Enter a complete birth date and exact time.');
    const desired = Date.UTC(year, month - 1, day, hour, minute);
    let guess = desired;
    const formatter = new Intl.DateTimeFormat('en-US', { timeZone: input.timezone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
    try {
        for (let i = 0; i < 4; i++) {
            const parts = Object.fromEntries(formatter.formatToParts(new Date(guess)).map(p => [p.type, p.value]));
            const represented = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
            guess += desired - represented;
        }
    }
    catch {
        throw new Error('Choose a valid IANA time zone for the birth place.');
    }
    return new Date(guess);
}

