function hexOverlap(h1, h2) {
  // Hamming agreement over the hex-encoded bit string.
  let same = 0, total = 0;
  for (let i = 0; i < Math.min(h1.length, h2.length); i++) {
    const d = parseInt(h1[i], 16) ^ parseInt(h2[i], 16);
    for (let b = 0; b < 4; b++) { total++; if (!((d >> b) & 1)) same++; }
