function largestComponent(mask, width, height) {
  const seen = new Uint8Array(width * height);
  let best = null;
  for (let start = 0; start < mask.length; start++) {
    if (!mask[start] || seen[start]) continue;
    const stack = [start];
    seen[start] = 1;
    const cells = [];
    let minX = width, maxX = 0, minY = height, maxY = 0, sx = 0, sy = 0;
    while (stack.length) {
      const i = stack.pop();
      cells.push(i);
      const x = i % width, y = (i / width) | 0;
      sx += x; sy += y;
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
      if (x > 0 && mask[i - 1] && !seen[i - 1]) { seen[i - 1] = 1; stack.push(i - 1); }
      if (x < width - 1 && mask[i + 1] && !seen[i + 1]) { seen[i + 1] = 1; stack.push(i + 1); }
      if (y > 0 && mask[i - width] && !seen[i - width]) { seen[i - width] = 1; stack.push(i - width); }
      if (y < height - 1 && mask[i + width] && !seen[i + width]) { seen[i + width] = 1; stack.push(i + width); }
    }
    if (!best || cells.length > best.cells.length) {
      best = { cells, bbox: { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 }, centroid: { x: sx / cells.length, y: sy / cells.length } };
    }
  }
  return best;
}

function solveAnalogy(a, b, c, registry) {
