function stableStringify(value) {
  const seen = new Set();

  const encode = (v) => {
    if (v === null) return 'null';
    const t = typeof v;
    if (t === 'string') return JSON.stringify(v);
    if (t === 'boolean') return v ? 'true' : 'false';
    if (t === 'number') return Number.isFinite(v) ? JSON.stringify(v) : 'null';
    if (t === 'undefined' || t === 'function' || t === 'symbol' || t === 'bigint') {
      return undefined;
    }
    if (Array.isArray(v)) {
      if (seen.has(v)) throw new TypeError('stableStringify: circular reference');
      seen.add(v);
      const out = '[' + v.map((item) => {
        const s = encode(item);
        return s === undefined ? 'null' : s;
      }).join(',') + ']';
      seen.delete(v);
      return out;
    }
    if (t === 'object') {
      if (seen.has(v)) throw new TypeError('stableStringify: circular reference');
      seen.add(v);
      const keys = Object.keys(v).sort();
      const parts = [];
      for (const key of keys) {
        const s = encode(v[key]);
        if (s !== undefined) parts.push(JSON.stringify(key) + ':' + s);
      }
      seen.delete(v);
      return '{' + parts.join(',') + '}';
    }
    return undefined;
  };

  const result = encode(value);
  return result === undefined ? 'null' : result;
}

function fnv1a32(str) {
  const bytes = new TextEncoder().encode(String(str));
  let hash = 0x811c9dc5;
  for (let k = 0; k < bytes.length; k++) {
    hash ^= bytes[k];
    // 32-bit multiply via Math.imul (plain `*` loses precision above 2^53).
    hash = Math.imul(hash, 0x01000193) >>> 0; // FNV prime 16777619
  }
  return hash.toString(16).padStart(8, '0');
}

function tokenMatches(token, keyword) {
  if (token === keyword) return true;
  if (token.length >= 4 && keyword.length >= 4) {
    return token.startsWith(keyword) || keyword.startsWith(token);
