function moveToAlgebraic(piece, from, to, captured, check, checkmate) {
    const files = 'abcdefgh';
    const ranks = '87654321';
    let notation = '';
    if (piece.type === 'p') {
        if (captured)
            notation += files[from[1]];
    }
    else {
        notation += piece.type.toUpperCase();
    }
    if (captured)
        notation += 'x';
    notation += files[to[1]] + ranks[to[0]];
    if (checkmate)
        notation += '#';
    else if (check)
        notation += '+';
    return notation;
}

