function createBoard(rows, cols, mines, safeRow, safeCol) {
    const board = Array.from({ length: rows }, () => Array.from({ length: cols }, () => ({ isMine: false, neighborMines: 0, state: 'hidden' })));
    let placed = 0;
    while (placed < mines) {
        const r = Math.floor(Math.random() * rows);
        const c = Math.floor(Math.random() * cols);
        if (board[r][c].isMine)
            continue;
        if (safeRow !== undefined && safeCol !== undefined && Math.abs(r - safeRow) <= 1 && Math.abs(c - safeCol) <= 1)
            continue;
        board[r][c].isMine = true;
        placed++;
    }
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (board[r][c].isMine)
                continue;
            let count = 0;
            for (let dr = -1; dr <= 1; dr++) {
                for (let dc = -1; dc <= 1; dc++) {
                    const nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc].isMine)
                        count++;
                }
            }
            board[r][c].neighborMines = count;
        }
    }
    return board;
}

