function explainPattern(pattern) {
    const explanations = [];
    const parts = pattern.split(/(\[.*?\]|\\.|\.|\*|\+|\?|\^|\$|\(\?[:=!]|\(|\)|\{|\}|\||\d+)/g).filter(Boolean);
    const meaningMap = {
        '.': 'Any character',
        '^': 'Start of string',
        '$': 'End of string',
        '\\d': 'Digit [0-9]',
        '\\w': 'Word character [a-zA-Z0-9_]',
        '\\s': 'Whitespace',
        '\\b': 'Word boundary',
        '*': 'Zero or more (greedy)',
        '+': 'One or more (greedy)',
        '?': 'Zero or one (optional)',
        '|': 'OR - alternation',
        '(': 'Start capturing group',
        ')': 'End capturing group',
        '{': 'Start quantifier',
        '}': 'End quantifier',
        '[': 'Start character class',
        ']': 'End character class',
    };
    for (const part of parts) {
        if (!part)
            continue;
        if (part.startsWith('[') && part.endsWith(']')) {
            explanations.push({ part, meaning: `Character class: ${part.slice(1, -1)}` });
        }
        else if (meaningMap[part]) {
            explanations.push({ part, meaning: meaningMap[part] });
        }
        else if (/^\\.$/.test(part)) {
            explanations.push({ part, meaning: `Escaped: ${part[1]}` });
        }
        else {
            explanations.push({ part, meaning: `Literal "${part}"` });
        }
    }
    return explanations;
}

