function parseCodeToAST(source, lang) {
    const root = { type: "Program", body: [] };
    if (lang === "js" || lang === "ts" || lang === "jsx" || lang === "tsx") {
        // Extract function declarations
        const funcRegex = /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g;
        let match;
        while ((match = funcRegex.exec(source)) !== null) {
            root.body.push({
                type: "FunctionDeclaration",
                name: match[1],
                params: match[2].split(",").map(s => s.trim()).filter(Boolean),
                loc: { start: match.index, end: match.index + match[0].length, line: source.slice(0, match.index).split("\n").length },
            });
        }
        // Extract variable declarations
        const varRegex = /(?:const|let|var)\s+(\w+)\s*=\s*([^;]+)/g;
        while ((match = varRegex.exec(source)) !== null) {
            root.body.push({
                type: "VariableDeclaration",
                name: match[1],
                value: match[2].trim(),
                loc: { start: match.index, end: match.index + match[0].length, line: source.slice(0, match.index).split("\n").length },
            });
        }
        // Extract class declarations
