      `.trim();
        }
        return '';
    }

const asGrammar = (value) => {
  if (!value) return {};
  if (!Array.isArray(value)) return { ...value };
  const out = {};
  value.forEach((rule, i) => {
    const key = rule?.lhs || rule?.id || `R${i + 1}`;
    out[key] = rule?.rhs ?? rule?.template ?? rule?.targetPattern ?? rule;
  });
  return out;
};

function jaccard(a, b) {
  const A = new Set(a), B = new Set(b);
  if (!A.size && !B.size) return 1;
  let hit = 0;
  for (const x of A) if (B.has(x)) hit++;
  return hit / Math.max(1, new Set([...A, ...B]).size);
}

function seeded(seed = 1) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function normalizeAstPayload(payload) {
  if (payload == null) return null;
  if (typeof payload === 'function') return { type:'function-source', source:payload.toString() };
  if (typeof payload === 'string') return { type:'source', source:payload };
  if (Array.isArray(payload)) return { type:'sequence', children:payload.map(normalizeAstPayload).filter(Boolean) };
  if (typeof payload === 'object') return structuredClone(payload);
  return null;
}

function validateSourceShape(source) {
  if (typeof source !== 'string' || !source.trim()) return { ok:false, reason:'EMPTY_SOURCE' };
  let depth = 0;
  for (const c of source) {
    if (c === '{') depth++;
    if (c === '}') depth--;
    if (depth < 0) return { ok:false, reason:'UNBALANCED_BRACES' };
  }
  return { ok:depth === 0, reason:depth === 0 ? null : 'UNBALANCED_BRACES' };
}

function cloneable(value) {
  try { return structuredClone(value); }
  catch { return value == null ? value : JSON.parse(JSON.stringify(value)); }
}

function normalizePath(path) {
  let out = String(path || '/').replace(/\\/g, '/');
  if (!out.startsWith('/')) out = '/' + out;
  out = out.replace(/\/+/g, '/');
  const parts=[];
  for (const part of out.split('/')) {
    if (!part || part === '.') continue;
    if (part === '..') parts.pop();
    else parts.push(part);
  }
  return '/' + parts.join('/');
}

function asText(artifact) {
  if (typeof artifact?.content === 'string') return artifact.content;
  if (typeof artifact?.originalContent === 'string') return artifact.originalContent;
  if (artifact?.bytes instanceof Uint8Array) return new TextDecoder().decode(artifact.bytes);
  return '';
}

function makeConsoleCapture() {
  const lines=[];
