  let classes = [accepting, rejecting].filter(x => x.length);

  while (true) {
    const classOf = new Map();
    classes.forEach((cls, i) => cls.forEach(s => classOf.set(s, i)));
    const refined = [];

    for (const cls of classes) {
      const buckets = new Map();
      for (const state of cls) {
        const signature = [...dfa.alphabet].map(symbol => classOf.get(dfa.step(state, symbol))).join('|');
        if (!buckets.has(signature)) buckets.set(signature, []);
        buckets.get(signature).push(state);
