        Who: 'Space', What: 'Movement', Where: 'Being', When: 'Evolution', Why: 'Design',
      },
      chronological: {
        First: 'Movement', Second: 'Evolution', Third: 'Being', Fourth: 'Design', Fifth: 'Space',
      },
      structural: {
        Foundation: 'Movement', Process: 'Evolution', Situation: 'Being', Form: 'Design', Identity: 'Space',
      },
    };

    const mapping = projections[projection] || projections.interrogative;
    const result = {};

    for (const [key, stageName] of Object.entries(mapping)) {
      const stage = trace.find((t) => t.stage === stageName);
      if (stage) {
        result[key] = { stage: stageName, output: stage.output, events: stage.events };
      }
    }

    return result;
  }

function transform(operands, context = {}) => {
      const members = operands.map((op, idx) => ({
        position: idx,
        stateId: op.id,
        scale: op.scale,
        text: op.text ? op.text.substring(0, 50) : op.id,
      }));
      // Donor ladder, verbatim (F2 examined, not a defect): sentence-only ->
      // paragraph; any paragraph/discourse operand -> discourse.
      const scales = new Set(operands.map((o) => o.scale));
      const resultScale = scales.has('discourse') ? 'discourse'
        : scales.has('paragraph') ? 'discourse'
        : 'paragraph';
      return {
        operator: 'o_discourse',
        members,
        scale: resultScale,
        unitCount: operands.length,
        context: { ...context },
      };
    }

function _adaptOperands(operands, targetScale) {
    // Phase-2 adaptation: wrap operands with target scale metadata.
    return operands.map((op) => ({ ...op, scale: targetScale, _adapted: true }));
  }

function _validateResult(result, expected) {
    if (!result || !expected) return false;
    // Loose validation for Phase 2 (source semantics preserved).
    return result.operator === expected.operator
      || (result.members && expected.members && result.members.length === expected.members.length);
  }

function _scoreRetrieval(found, expected) {
    const foundSet = new Set(found.map((f) => f.id));
    const expectedSet = new Set(expected);
    const intersection = new Set([...foundSet].filter((x) => expectedSet.has(x)));
    return expectedSet.size > 0 ? intersection.size / expectedSet.size : 0;
  }

function _estimateDirectSize(primitives) {
    return primitives.length * 50; // source: "rough bytes per primitive"
  }

function _matchPrediction(predicted, expected) {
    // Loose matching for Phase 2 (source semantics preserved).
    return predicted.confidence > 0.3;
  }

function _sharedComponents(addresses) {
    if (addresses.length === 0) return [];
    const keys = Object.keys(addresses[0]);
    return keys.filter((k) => addresses.every((a) => a[k] === addresses[0][k] && a[k] != null));
  }

function evaluatePredictive(mappingFn, dataset) {
    let correct = 0;
    for (const item of dataset) {
      const predicted = mappingFn(item.index);
      if (predicted.id === item.expectedDimension) correct += 1;
    }
    return dataset.length > 0 ? correct / dataset.length : 0;
  }

function _measureCoherence(dimensions) {
    // Simple coherence: shared properties across dimensions.
    if (dimensions.length < 2) return 1.0;
    const shared = new Set();
    const first = dimensions[0];
    if (!first) return 0;
    for (const key of Object.keys(first)) {
      if (dimensions.every((d) => d && d[key] === first[key])) shared.add(key);
    }
    return shared.size / Object.keys(first).length;
  }

function _inferRelation(dimA, dimB) {
    if (!dimA || !dimB) return 'unknown';
    if (dimA.id === dimB.id) return 'identity';
    if (dimA.macroName === dimB.macroName) return 'same_macro';
    if (dimA.keynote === dimB.keynote) return 'same_keynote';
    return 'unrelated';
  }

function transform(operands) {
