function flattenToScale(token, targetScale) {
    const results = [];
    const visit = (node) => {
      if (node.scale === targetScale || node.type === targetScale) {
        results.push(node);
        return;
      }
      for (const child of node.children || []) visit(child);
    };
    visit(token);
    return results;
  }

function scalePath(token) {
    const path = [];
    const visit = (node, depth = 0) => {
      path.push({ type: node.type, scale: node.scale, depth, text: node.text.substring(0, 20) });
      for (const child of node.children || []) visit(child, depth + 1);
    };
    visit(token);
    return path;
  }

function transform(operand, context = {}) {
      const { operator, depth = 1, maxDepth = 8 } = context;
      if (typeof operator !== 'function') throw new TypeError('o_recurse requires context.operator (function)');
      const d = Math.min(Math.max(0, depth | 0), maxDepth);
      let value = operand;
      const trace = [];
      for (let i = 0; i < d; i++) { value = operator(value); trace.push(value); }
      return { kind:'recursion', operator:'o_recurse', depth: d, maxDepth, input: operand, output: value, trace,
               ledger: { recursionDepth: d } };
    }

function ls(args, ctx) => {
        const targetPath = args[0] || ctx.currentPath;
        const node = ctx.findNodeByPath(targetPath);
        if (!node)
            return `ls: cannot access '${targetPath}': No such file or directory`;
        if (node.type === 'file')
            return node.name;
        const children = ctx.getChildren(node.id);
        if (children.length === 0)
            return '';
        return children.map((c) => {
            const prefix = c.type === 'folder' ? '\x1b[34m' : '\x1b[0m';
            const suffix = '\x1b[0m';
            return `${prefix}${c.name}${suffix}`;
        });
    }

function cd(args, ctx) => {
        if (!args[0] || args[0] === '~') {
            ctx.setCurrentPath('/home/user');
            return '';
        }
        let target = args[0];
        if (target.startsWith('/')) {
            const node = ctx.findNodeByPath(target);
            if (!node)
                return `cd: no such file or directory: ${target}`;
            if (node.type !== 'folder')
                return `cd: not a directory: ${target}`;
            ctx.setCurrentPath(target);
            return '';
        }
        // Relative path
        const currentParts = ctx.currentPath.split('/').filter(Boolean);
        const parts = target.split('/').filter(Boolean);
        for (const part of parts) {
            if (part === '..') {
                currentParts.pop();
            }
            else if (part !== '.') {
                currentParts.push(part);
            }
        }
        const newPath = '/' + currentParts.join('/');
        const node = ctx.findNodeByPath(newPath);
        if (!node)
            return `cd: no such file or directory: ${target}`;
        if (node.type !== 'folder')
            return `cd: not a directory: ${target}`;
        ctx.setCurrentPath(newPath);
        return '';
    }

function mkdir(args, ctx) => {
        if (!args[0])
            return 'mkdir: missing operand';
        const currentNode = ctx.findNodeByPath(ctx.currentPath);
        if (!currentNode)
            return 'mkdir: cannot create directory';
        ctx.createFolder(currentNode.id, args[0]);
        return '';
    }

function touch(args, ctx) => {
        if (!args[0])
            return 'touch: missing file operand';
        const currentNode = ctx.findNodeByPath(ctx.currentPath);
        if (!currentNode)
            return 'touch: cannot create file';
        ctx.createFile(currentNode.id, args[0]);
        return '';
    }

function rm(args, ctx) => {
        if (!args[0])
            return 'rm: missing operand';
        const currentNode = ctx.findNodeByPath(ctx.currentPath);
        if (!currentNode)
            return 'rm: cannot remove';
        const children = ctx.getChildren(currentNode.id);
        const target = children.find((c) => c.name === args[0]);
        if (!target)
            return `rm: cannot remove '${args[0]}': No such file or directory`;
        ctx.deleteNode(target.id);
        return '';
    }

function cat(args, ctx) => {
        if (!args[0])
            return 'cat: missing file operand';
        const currentNode = ctx.findNodeByPath(ctx.currentPath);
        if (!currentNode)
            return 'cat: cannot read file';
        const children = ctx.getChildren(currentNode.id);
        const target = children.find((c) => c.name === args[0]);
        if (!target)
            return `cat: '${args[0]}': No such file or directory`;
        if (target.type === 'folder')
            return `cat: '${args[0]}': Is a directory`;
        const content = ctx.readFile(target.id);
        return content || '';
    }

function clear(_args, ctx) => {
