function generateResponse(input, learned) {
        if (learned.length === 0) {
            return `Input: "${input.substring(0, 50)}" - No pattern match. This represents novel data for my grammar.\n\nCan you provide another example? I learn from multiple instances.`;
        }
        const mainPattern = learned[0];
        const responses = [
            `Pattern recognized: ${mainPattern.pattern} (${mainPattern.category})\nConfidence: ${(mainPattern.confidence * 100).toFixed(1)}%`,
            `Analysis: "${mainPattern.rule?.rhs[1] || 'Pattern identified'}"`,
            learned.length > 1 ? `Additional patterns: ${learned.slice(1).map(l => l.pattern).join(', ')}` : ''
