function mode(arr) {
        const counts = {};
        arr.forEach(item => { counts[item] = (counts[item] || 0) + 1; });
        const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 && sorted[0][1] > 1 ? sorted[0][0] : null;
