function detectCode(input) {
        const codeIndicators = [
            /\bfunction\b|\bconst\b|\blet\b|\bvar\b|\bclass\b/,
            /\bif\s*\(|\bfor\s*\(|\bwhile\s*\(/,
            /[{};]\s*$/m,
