function buildParseTree(codedWords) {
        const nodes = [];
        // Build flat structure first
        codedWords.forEach((cw, i) => {
            nodes.push({
                id: `node_${i}`,
                label: `${cw.token} [${cw.pos}]`,
                children: [],
                start: i,
                end: i + 1
            });
        });
        // Attempt phrase grouping (simplified)
        const phraseGroups = [];
        let currentPhrase = [];
        codedWords.forEach((cw) => {
            if (cw.pos === 'DET' || cw.pos === 'ADJ' || cw.pos === 'N') {
                currentPhrase.push(cw);
            }
            else {
                if (currentPhrase.length > 0) {
                    const start = codedWords.indexOf(currentPhrase[0]);
                    phraseGroups.push({
                        id: `np_${phraseGroups.length}`,
                        label: `NP (${currentPhrase.map(p => p.token).join(' ')})`,
                        children: currentPhrase.map((_, i) => `node_${start + i}`),
                        start,
                        end: start + currentPhrase.length
                    });
                    currentPhrase = [];
                }
            }
        });
        nodes.push(...phraseGroups);
        return {
            root: 'S',
            nodes,
            depth: phraseGroups.length > 0 ? 2 : 1,
            confidence: 0.7
        };
    }

function inferStructuralPattern(codedWords) {
        const pattern = codedWords.map(cw => cw.pos).join(' ');
        // Detect common patterns
        if (pattern.includes('DET N V'))
            return 'S -> NP VP (declarative)';
        if (pattern.includes('V N'))
            return 'S -> VP NP (imperative/inverted)';
        if (pattern.startsWith('AUX'))
            return 'S -> Aux NP VP (interrogative)';
        if (pattern.includes('PREP DET N'))
            return 'S -> NP PP (prepositional)';
        return `S -> ${pattern}`;
    }

function getCodeFeatures(type, _text) {
        const featureMap = {
