            IDENTIFIER: { user_defined: 'true', semantic: 'true' },
            LITERAL: { constant: 'true', evaluable: 'true' },
            OPERATOR: { operation: 'true', precedence: 'varies' },
            COMMENT: { executable: 'false', documentation: 'true' },
            TYPE: { type_system: 'true', annotation: 'true' }
