function buildCodeParseTree(tokens) {
        const nodes = [];
        const blockStack = [];
        tokens.forEach((t, i) => {
            const node = {
                id: `token_${i}`,
                label: `${t.text} [${t.type}]`,
                children: [],
                start: i,
                end: i + 1
            };
            if (t.text === '{' || t.text === '(') {
                blockStack.push(node);
            }
            else if ((t.text === '}' || t.text === ')') && blockStack.length > 0) {
                const block = blockStack.pop();
                block.end = i + 1;
                block.label = `BLOCK (${block.start}-${block.end})`;
                nodes.push(block);
            }
            else {
                nodes.push(node);
            }
        });
        return {
            root: 'PROGRAM',
            nodes,
            depth: 3,
            confidence: 0.85
        };
    }

function calculateComplexity(input) {
        const lines = input.split('\n').filter(l => l.trim());
        const tokens = input.match(/\b\w+\b/g) || [];
        // Cyclomatic complexity approximation
        const decisions = (input.match(/\b(if|else|while|for|case|&&|\|\|)\b/g) || []).length;
        // Halstead metrics approximation
        const operators = new Set(input.match(/[\+\-\*\/=<>!&|:]+/g) || []);
        const operands = new Set(tokens);
        const halsteadLength = operators.size + operands.size;
        const halsteadVocabulary = new Set([...Array.from(operators), ...Array.from(operands)]).size;
        return {
            linesOfCode: lines.length,
            tokenCount: tokens.length,
            cyclomaticComplexity: decisions + 1,
            halsteadLength,
            halsteadVocabulary,
            uniqueOperators: operators.size,
            uniqueOperands: operands.size,
            averageLineLength: lines.reduce((sum, l) => sum + l.length, 0) / Math.max(lines.length, 1)
        };
    }

