        }
        if (lower.includes('mean') || lower.includes('semantic') || lower.includes('what is') || lower.includes('define') || lower.includes('similar')) {
            systems.push('diseminer');
        }
        if (lower.includes('learn') || lower.includes('pattern') || lower.includes('grammar') || lower.includes('language')) {
            systems.push('autoling');
        }
        if (lower.includes('evolve') || lower.includes('change') || lower.includes('history') || lower.includes('simulate')) {
