function explainForBeginner(code) {
        const lines = code.split('\n');
        let explanation = '// STEP-BY-STEP EXPLANATION:\n';
        lines.forEach((line, i) => {
            const trimmed = line.trim();
            if (trimmed.startsWith('//') || trimmed.startsWith('*')) {
                explanation += `// Line ${i + 1}: This is a comment (notes for humans)\n`;
            }
            else if (trimmed.includes('function') || trimmed.includes('=>')) {
                explanation += `// Line ${i + 1}: This creates an action the computer can do\n`;
            }
            else if (trimmed.includes('const ') || trimmed.includes('let ') || trimmed.includes('var ')) {
                explanation += `// Line ${i + 1}: This stores information in a labeled box\n`;
            }
            else if (trimmed.includes('if ') || trimmed.includes('else')) {
                explanation += `// Line ${i + 1}: This makes a decision\n`;
            }
            else if (trimmed.includes('for ') || trimmed.includes('while')) {
                explanation += `// Line ${i + 1}: This repeats something\n`;
            }
            else if (trimmed.includes('return')) {
                explanation += `// Line ${i + 1}: This sends back a result\n`;
            }
            else if (trimmed.includes('class ')) {
                explanation += `// Line ${i + 1}: This defines a blueprint for objects\n`;
            }
            else if (trimmed.trim()) {
                explanation += `// Line ${i + 1}: This does something with the data\n`;
            }
        });
        return explanation;
    }

