function inferComplexity(code) {
        if (code.includes('for') && code.match(/for.*for/s))
            return 'O(n^2) - nested iteration';
        if (code.includes('while'))
            return 'O(n) - linear scan with condition';
        if (code.includes('recur'))
            return 'O(2^n) - recursive branching';
        if (code.includes('sort'))
            return 'O(n log n) - comparison sort';
        return 'O(n) - single pass';
    }

function inferSpaceComplexity(code) {
        if (code.includes('new Array') || code.includes('[]'))
            return 'O(n) - array storage';
        if (code.includes('Map') || code.includes('Set'))
            return 'O(n) - hash table overhead';
        if (code.includes('recur'))
            return 'O(log n) - call stack depth';
        return 'O(1) - constant space';
    }

function inferPattern(code) {
        if (code.includes('class') && code.includes('extends'))
            return 'Inheritance/Template Method';
        if (code.includes('=>') && code.includes('map'))
            return 'Functional/Map-Reduce';
        if (code.includes('Promise') || code.includes('async'))
            return 'Async/Concurrent';
        if (code.includes('factory') || code.includes('create'))
            return 'Factory/Creational';
        if (code.includes('observer') || code.includes('emit'))
            return 'Observer/Event-Driven';
        return 'Procedural';
    }

