                code = cleaned.join("\n");
            }
        }
        // Add JSDoc if missing
        if (/function\s+\w+/.test(code) && !/\/\*\*/.test(code)) {
            code = code.replace(/function\s+(\w+)\s*\(([^)]*)\)\s*\{/g, (_, name, params) => {
