            const detriment = activeState.activation * (1 - colorRatio);
            activeState.activation = Math.sqrt(exaltation ** 2 + detriment ** 2 +
                2 * exaltation * detriment * Math.cos(toneFreq * Math.PI));
            activeState.phase += toneFreq * Math.PI;
