    if (ws[0].toUpperCase() === 'BE') return { cop: true, verb: 'be', rest: ws.slice(1).join(' ').toLowerCase() };
    return { cop: false, verb: ws[0], rest: ws.slice(1).join(' ').toLowerCase() };
  }

function sentHasVars(s) {
      const fv = f => f && (f.k === 'svar' || f.k === 'svardef');
      return fv(s.s) || fv(s.r) || fv(s.o);
    }

function updateVars(sent, env, hits, result) {
      for (const pos of ['s', 'r', 'o']) {
        const f = sent[pos];
        if (!f || (f.k !== 'svar' && f.k !== 'svardef')) continue;
        if (!result) { env.svars.set(f.name, []); continue; }
        const keep = hits[pos];
        env.svars.set(f.name, env.svars.get(f.name).filter(x => keep.has(x)));
      }
    }

