function hashInput(input) {
        const str = JSON.stringify(input);
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash; // Convert to 32-bit integer
        }
        return Math.abs(hash);
    }

function calculateResonanceScore(addr1, addr2) {
        let score = 1.0;
        // Same mesh = high resonance
        if (addr1.mesh === addr2.mesh)
            score += 0.2;
        // Same layer = high resonance
        if (addr1.layer === addr2.layer)
            score += 0.2;
        // Same center = medium resonance
        if (addr1.center === addr2.center)
            score += 0.15;
        // Same line = medium resonance
        if (addr1.line === addr2.line)
            score += 0.15;
        // Similar zodiac = low resonance
        const zodiacDiff = Math.abs(addr1.zodiac - addr2.zodiac);
        score += (1 - (zodiacDiff / 6)) * 0.1;
        return score;
    }

