function _canonConflicts(engine) {
    const canon = engine && (engine.canon || engine.canonRegistry);
    if (!canon) return 0;
    try {
      const entries = typeof canon.entries === 'function' ? canon.entries()
        : canon.entries instanceof Map ? [...canon.entries.values()]
        : Array.isArray(canon.entries) ? canon.entries
        : [];
      return entries.filter((e) => e && Array.isArray(e.conflicts) && e.conflicts.length > 0).length;
    } catch {
      return 0;
    }
  }

function detectFileType(filename) {
        const ext = filename.split(".").pop()?.toLowerCase() || "";
        const typeMap = {
            "tsx": "tsx", "ts": "ts", "js": "js", "jsx": "jsx",
            "py": "py", "json": "json", "css": "css", "md": "md"
        };
        return typeMap[ext] || "unknown";
    }

function extractExports(content) {
        const exports = [];
        const defaultMatch = content.match(/export\s+default\s+(?:function|class|const)?\s*(\w+)/);
        if (defaultMatch)
            exports.push(`default:${defaultMatch[1]}`);
        const namedMatches = content.matchAll(/export\s+(?:function|class|const|type|interface)\s+(\w+)/g);
        for (const match of namedMatches) {
            exports.push(match[1]);
        }
        return exports;
    }

function extractImports(content) {
        const imports = [];
        const matches = content.matchAll(/import\s+.*?\s+from\s+['"]([^'"]+)['"]/g);
        for (const match of matches) {
            imports.push(match[1]);
        }
        return imports;
    }

function extractProps(content) {
        const props = [];
        const interfaceMatch = content.match(/interface\s+\w+Props\s*\{([^}]+)\}/);
        if (interfaceMatch) {
            const propsBlock = interfaceMatch[1];
            const propMatches = propsBlock.matchAll(/(\w+)(\?)?:\s*(\w+)/g);
            for (const match of propMatches) {
                props.push({
                    name: match[1],
                    type: match[3],
                    required: !match[2],
                });
            }
        }
        const destructMatch = content.match(/\{\s*([^}]+)\}\s*:\s*\w+Props/);
        if (destructMatch) {
            const propNames = destructMatch[1].split(",").map(s => s.trim());
            for (const name of propNames) {
                if (!props.find(p => p.name === name)) {
                    props.push({ name, type: "unknown", required: true });
                }
            }
        }
        return props;
    }

function extractElementProps(jsx, tag) {
        const props = {};
        const propRegex = /(\w+)=\{([^}]+)\}|(\w+)="([^"]*)"/g;
        let match;
        while ((match = propRegex.exec(jsx)) !== null) {
            const key = match[1] || match[3];
            const val = match[2] || match[4];
            if (key && key !== tag) {
                props[key] = val;
            }
        }
        return props;
    }

function extractChildren(jsx) {
        const children = [];
        const childRegex = /<(\w+)[^>]*>([^<]*)<\/\1>/g;
        let match;
        while ((match = childRegex.exec(jsx)) !== null) {
            if (match[1] !== "div" && match[1] !== "span") {
                children.push({
                    element: match[1],
                    text: match[2] || undefined
                });
            }
        }
        return children.length > 0 ? children : undefined;
    }

function extractStateShape(content) {
        const stateShape = {};
        const stateMatches = content.matchAll(/const\s+\[(\w+),\s*set(\w+)\]\s*=\s*useState(?:<([^>]+)>)?\(([^)]+)\)/g);
        for (const match of stateMatches) {
            stateShape[match[1]] = match[3] || "any";
        }
        const reducerMatch = content.match(/useReducer\((\w+),\s*\{([^}]+)\}\)/);
        if (reducerMatch) {
            const initProps = reducerMatch[2].matchAll(/(\w+):\s*(\w+)/g);
            for (const match of initProps) {
                stateShape[match[1]] = match[2];
            }
        }
        return Object.keys(stateShape).length > 0 ? stateShape : undefined;
    }

function extractBlueprint(content) {
        const imports = [...content.matchAll(/import\s+.*?\s+from\s+['"]([^'"]+)['"]/g)].map(m => m[0]);
        const exports = [...content.matchAll(/export\s+(?:default\s+)?(?:function|const|class|interface|type)\s+\w+/g)].map(m => m[0]);
        const functions = [...content.matchAll(/(?:function|const)\s+(\w+)/g)].map(m => m[1]);
        const classes = [...content.matchAll(/class\s+(\w+)/g)].map(m => m[1]);
        const hasJsx = content.includes("return (") && (content.includes("<") || content.includes("div"));
        // Determine file role
        let fileRole = "utility";
        if (hasJsx)
            fileRole = "component";
        else if (exports.some(e => e.includes("default")))
            fileRole = "module";
        else if (classes.length > 0)
            fileRole = "class";
        else if (functions.length > 0)
            fileRole = "functions";
        return {
            imports,
            exports,
            functions,
            classes,
            hasJsx,
            fileRole,
            chunkCount: Math.ceil(content.length / 2000),
            totalLength: content.length
        };
    }

function _calculateIntentDepth(record) {
        const { structure } = record;
        let depth = 1;
        if (structure.classes.length > 0)
            depth++;
        if (structure.imports.length > 0)
            depth++;
        if (structure.complexity.score > 20)
            depth++;
        if (structure.functions.length > 10)
            depth++;
        return depth;
    }

function _calculateSophistication(record, causality) {
        const { structure } = record;
        let score = 0;
        if (structure.classes.length > 0)
            score += 2;
        if (structure.imports.length > 2)
            score += 1;
        if (structure.complexity.score > 30)
            score += 2;
        if (Object.keys(causality.functions).length > 5)
            score += 1;
        if (record.behavior.intents.length > 2)
            score += 2;
        return score;
    }

function _mapRelationships(record, causality) {
        const { structure } = record;
        return { internal: structure.dependencies, external: structure.imports.map((imp) => ({ module: imp, type: 'import' })), behavioral: record.behavior.actions.map((a) => ({ action: a, triggeredBy: [] })), causal: causality };
    }

function _suggestImprovements(record, preferences) {
        const suggestions = [];
        const { structure, behavior } = record;
        if (structure.complexity.score > 50)
            suggestions.push('modularize: split into smaller modules');
        if (!behavior.intents.includes('memory') && structure.functions.length > 3)
            suggestions.push('add-persistence: learn from usage patterns');
        if (!behavior.intents.includes('network') && structure.imports.length > 0)
            suggestions.push('add-sync: connect to remote storage');
        if (preferences.likes?.includes('minimal'))
            suggestions.push('minimize: remove unused functions');
        if (preferences.likes?.includes('chat'))
            suggestions.push('add-chat: conversational interface');
        return suggestions;
    }

function _calculateConfidence(causality, intent) {
        const fnCount = Object.keys(causality.functions).length;
        const knownPurposes = Object.values(causality.functions).filter((f) => f.purpose !== 'utility').length;
        const ratio = fnCount > 0 ? knownPurposes / fnCount : 0;
        return Math.min(0.95, 0.3 + ratio * 0.6 + intent.depth * 0.05);
    }

function extractTextFromParsed(parsedFile) {
        const parts = [];

        // Add file name
        parts.push(parsedFile.fileName || '');

        // Add structure text
        if (parsedFile.structure) {
            const structure = parsedFile.structure;

            // Functions
            if (structure.functions) {
                for (const fn of structure.functions) {
                    parts.push(fn.name || '');
                }
            }

            // Classes
            if (structure.classes) {
                for (const cls of structure.classes) {
                    parts.push(cls.name || '');
                }
            }

            // Variables
            if (structure.variables) {
                for (const v of structure.variables) {
                    parts.push(v.name || '');
                }
            }

            // Imports
            if (structure.imports) {
                for (const imp of structure.imports) {
                    parts.push(imp.source || imp.path || '');
                }
            }

            // Comments
            if (structure.comments) {
                for (const comment of structure.comments) {
                    parts.push(comment.text || comment.content || '');
                }
            }

            // Headers (markdown)
            if (structure.headers) {
                for (const h of structure.headers) {
                    parts.push(h.text || '');
                }
            }

            // Top-level keys (JSON)
            if (structure.topLevelKeys) {
                parts.push(...structure.topLevelKeys);
            }
        }

        // Add raw preview
        if (parsedFile.rawPreview) {
            parts.push(parsedFile.rawPreview.slice(0, 1000));
        }

        return parts.join(' ');
    }

function calculateEntityConfidence(type, value, parsedFile) {
        let confidence = 0.7;

        // Higher confidence for well-formed values
        if (type === 'email' && value.includes('@') && value.includes('.')) confidence = 0.95;
        if (type === 'url' && value.startsWith('http')) confidence = 0.95;
        if (type === 'uuid' && value.length === 36) confidence = 0.99;
        if (type === 'hash' && value.length >= 32) confidence = 0.9;

        // Lower confidence for short/generic values
        if (value.length < 3) confidence *= 0.5;
        if (/^[A-Z]$/.test(value)) confidence *= 0.3;

        return confidence;
    }

function hashString(str) {
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return Math.abs(hash).toString(36);
    }

function calculateConfidence(parsedFile, entities, concepts, purpose) {
        let confidence = 0.5;

        // Higher confidence for well-structured files
        if (parsedFile.structure) {
            if (parsedFile.structure.lineCount > 0) confidence += 0.1;
            if (parsedFile.structure.complexity > 0) confidence += 0.1;
        }

        // Higher confidence with more entities
        if (entities.length > 5) confidence += 0.1;
        if (entities.length > 20) confidence += 0.1;

