function easeValue(t, type = 'linear') {
    switch (type) {
      case 'easeIn':
        return t * t;
      case 'easeOut':
        return t * (2 - t);
      case 'easeInOut':
        return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
      case 'cubic':
        return t < 0.5 ? 4 * t * t * t : 1 + (t - 1) * (2 * (t - 2)) * (2 * (t - 2));
      case 'elastic':
        const c5 = (2 * Math.PI) / 4.5;
        return t === 0
          ? 0
          : t === 1
            ? 1
            : -Math.pow(2, 10 * t - 10) * Math.sin((t * 10 - 10.75) * c5);
      case 'bounce':
        return t < 0.5
          ? (1 - Math.cos(Math.PI * t)) / 2
          : (1 + Math.cos(Math.PI * (t - 1))) / 2;
      default:
        return t;
    }
  }

