function incrementVersion(version) {
    const [major, minor, patch] = version.split('.').map(Number);
    return `${major}.${minor}.${patch + 1}`;
}

function getBasinColor(basin) {
    const colors = {
        center: '#6366f1',
        identity: '#ec4899',
        control: '#6b7280',
        insight: '#10b981',
        exploration: '#f59e0b',
        connection: '#8b5cf6',
        memory: '#06b6d4',
        action: '#ef4444',
        misc: '#9ca3af'
    };
    return colors[basin] || '#9ca3af';
}

function inferCommand(capability, intent) {
        const type = intent.type;
        switch (capability.id) {
            case 'git.pull': return 'git pull --ff-only';
            case 'deps.install': return 'npm install';
            case 'deps.clean': return 'rm -rf node_modules package-lock.json && npm install';
            case 'project.build': return 'npm run build';
            case 'service.restart': return 'pm2 restart all || pm2 start ecosystem.config.js || pm2 start npm --name app -- start';
            case 'service.health': return 'sleep 3 && curl -s http://localhost:3000/health || curl -s http://localhost:3000 || echo "OK"';
            case 'service.stop': return 'pm2 stop all';
            case 'git.reset': return 'git reset --hard HEAD~1';
            case 'build.clean': return 'rm -rf dist build';
            default: return 'echo "No command inferred"';
        }
    }

function inferDomainFromIntent(intent) {
        const codeKeywords = ['github', 'repo', 'code', 'javascript', 'python', 'typescript', 'rust', 'implementation'];
        const researchKeywords = ['paper', 'arxiv', 'research', 'algorithm', 'model', 'neural'];
        const medicalKeywords = ['medical', 'clinical', 'patient', 'disease', 'treatment', 'pubmed'];
        const lower = intent.raw.toLowerCase();
        if (medicalKeywords.some(k => lower.includes(k)))
            return 'medical';
        if (researchKeywords.some(k => lower.includes(k)))
            return 'research';
        if (codeKeywords.some(k => lower.includes(k)))
            return 'code';
        return 'general';
    }

function extractXmlTag(xml, tag) {
        const match = xml.match(new RegExp(`<${tag}[^>]*>([\s\S]*?)<\/${tag}>`));
        return match ? match[1].trim() : null;
    }

function scorePaper(title, summary, category) {
        let score = 0.5;
        // Boost recent papers, high-citation categories, etc.
        const highImpactCats = ['cs.AI', 'cs.LG', 'cs.CL', 'stat.ML', 'q-bio.BM'];
        if (highImpactCats.includes(category))
            score += 0.2;
        if (title.toLowerCase().includes('transformer') || title.toLowerCase().includes('llm'))
            score += 0.1;
        return Math.min(score, 0.95);
    }

function synthesize(docs, query) {
        if (docs.length === 0)
            return `No arXiv results found for "${query.text}". Try a more specific research query.`;
