            synth += `### Top Repositories\n`;
            repos.forEach(r => {
                synth += `- **${r.title}** (${r.metadata.stars}⭐) — ${r.content.split('\n')[0]}\n`;
                synth += `  [${r.url}]\n`;
            });
            synth += `\n`;
