function scoreArticle(title, journal, year) {
        let score = 0.5;
        const highImpactJournals = ['Nature', 'Science', 'Cell', 'NEJM', 'Lancet', 'JAMA', 'BMJ', 'PNAS'];
        if (highImpactJournals.some(j => journal.toLowerCase().includes(j.toLowerCase())))
            score += 0.2;
        const yearNum = parseInt(year);
        if (!isNaN(yearNum) && yearNum >= 2020)
            score += 0.15;
        if (title.toLowerCase().includes('randomized') || title.toLowerCase().includes('trial'))
            score += 0.1;
        return Math.min(score, 0.95);
    }

