        if (lower.includes('how to') || lower.includes('implement') || lower.includes('build'))
            return 'implementation';
        if (lower.includes('what is') || lower.includes('explain'))
            return 'explanation';
        if (lower.includes('compare') || lower.includes('vs'))
            return 'comparison';
        if (lower.includes('latest') || lower.includes('recent'))
