function determineTypeFromLanguage(language, code) {
        if (language.includes('react') || language.includes('jsx') || language.includes('tsx'))
            return 'react_component';
        if (code.includes('useState') || code.includes('useEffect'))
            return 'hook';
        if (language.includes('css') || language.includes('scss'))
            return 'style';
        if (code.includes('app.get') || code.includes('router.'))
            return 'api_route';
        if (code.includes('schema') || code.includes('table'))
            return 'schema';
        return 'utility';
    }

function normalizeLanguage(language) {
        const langMap = {
            'js': 'javascript',
            'jsx': 'javascript-react',
            'ts': 'typescript',
            'tsx': 'typescript-react',
            'py': 'python',
            'html': 'html',
            'css': 'css',
            'json': 'json',
            'md': 'markdown'
        };
        return langMap[language.toLowerCase()] || language;
    }

function detectCodeInPlainText(content) {
        // Check for HTML
        if (content.includes('<html') || content.includes('<!DOCTYPE')) {
            return { type: 'utility', language: 'html', extension: 'html' };
        }
        // Check for JSON
        if (content.trim().startsWith('{') && content.trim().endsWith('}')) {
            try {
                JSON.parse(content);
                return { type: 'schema', language: 'json', extension: 'json' };
            }
            catch { }
        }
        // Check for CSS
        if (content.includes('{') && content.includes('}') && (content.includes('color:') || content.includes('margin:') || content.includes('padding:'))) {
            return { type: 'style', language: 'css', extension: 'css' };
        }
        // Check for Python
        if (/(^|\n)\s*(?:def\s+\w+\s*\(|from\s+[\w.]+\s+import\s+|import\s+[\w.]+\s*$)/m.test(content)) {
            return { type: 'utility', language: 'python', extension: 'py' };
        }
        // Check for JavaScript/React
        if (content.includes('function ') || content.includes('const ') || content.includes('export ')) {
            if (content.includes('React') || content.includes('useState')) {
                return { type: 'react_component', language: 'javascript-react', extension: 'jsx' };
            }
            return { type: 'utility', language: 'javascript', extension: 'js' };
        }
        return null;
    }

