    if (contentType === 'javascript') {
        const functions = content.split('\n').filter(line => /(?:^|\s)(?:function|class)\s+\w+|=>/.test(line));
        return { type: contentType, module_name: moduleName, functions, raw: content.substring(0, 500) };
