function _sampleSurface(gltf, count, out) {
  // ── 1. Collect all triangles from all meshes in world space ──
  const tris = [];  // flat array: [ax,ay,az, bx,by,bz, cx,cy,cz, ...]
  gltf.scene.updateWorldMatrix(true, true);
  gltf.scene.traverse(obj => {
    if (!obj.isMesh) return;
    const pos = obj.geometry.attributes.position;
    const idx = obj.geometry.index;
    const m   = obj.matrixWorld.elements;  // column-major 4×4
    const triCount = idx ? Math.floor(idx.count / 3) : Math.floor(pos.count / 3);
    for (let t = 0; t < triCount; t++) {
      const i0 = idx ? idx.getX(t*3)   : t*3;
      const i1 = idx ? idx.getX(t*3+1) : t*3+1;
      const i2 = idx ? idx.getX(t*3+2) : t*3+2;
      const ax=pos.getX(i0), ay=pos.getY(i0), az=pos.getZ(i0);
      const bx=pos.getX(i1), by=pos.getY(i1), bz=pos.getZ(i1);
      const cx=pos.getX(i2), cy=pos.getY(i2), cz=pos.getZ(i2);
      // Transform each vertex: tx = m[0]*x + m[4]*y + m[8]*z + m[12]  (Three.js col-major)
      tris.push(
        m[0]*ax+m[4]*ay+m[8]*az+m[12], m[1]*ax+m[5]*ay+m[9]*az+m[13], m[2]*ax+m[6]*ay+m[10]*az+m[14],
        m[0]*bx+m[4]*by+m[8]*bz+m[12], m[1]*bx+m[5]*by+m[9]*bz+m[13], m[2]*bx+m[6]*by+m[10]*bz+m[14],
        m[0]*cx+m[4]*cy+m[8]*cz+m[12], m[1]*cx+m[5]*cy+m[9]*cz+m[13], m[2]*cx+m[6]*cy+m[10]*cz+m[14]
      );
    }
  });

  const numTris = (tris.length / 9) | 0;
  if (!numTris) return;

  // ── 2. Compute cumulative area for area-weighted triangle sampling ──
  const cumArea = new Float64Array(numTris);
  let total = 0;
  for (let t = 0; t < numTris; t++) {
    const b  = t * 9;
    const ex = tris[b+3]-tris[b],   ey = tris[b+4]-tris[b+1], ez = tris[b+5]-tris[b+2];
    const fx = tris[b+6]-tris[b],   fy = tris[b+7]-tris[b+1], fz = tris[b+8]-tris[b+2];
    total += 0.5 * Math.sqrt((ey*fz-ez*fy)**2 + (ez*fx-ex*fz)**2 + (ex*fy-ey*fx)**2);
    cumArea[t] = total;
  }

  // ── 3. Bounding box → normalize all points to [-1, 1] ──
  let minX=Infinity, minY=Infinity, minZ=Infinity;
  let maxX=-Infinity, maxY=-Infinity, maxZ=-Infinity;
  for (let v = 0; v < tris.length; v += 3) {
    const x=tris[v], y=tris[v+1], z=tris[v+2];
    if (x<minX) minX=x; if (x>maxX) maxX=x;
    if (y<minY) minY=y; if (y>maxY) maxY=y;
    if (z<minZ) minZ=z; if (z>maxZ) maxZ=z;
  }
  const ocx=(minX+maxX)*0.5, ocy=(minY+maxY)*0.5, ocz=(minZ+maxZ)*0.5;
  const sc = 2.0 / Math.max(maxX-minX, maxY-minY, maxZ-minZ, 1e-6);

  // ── 4. Sample count surface points deterministically ──
  for (let i = 0; i < count; i++) {
    // Triangle selection: golden-ratio-distributed across total area
    const u   = (i * 0.618034) % 1.0;
    const tgt = u * total;
    let lo = 0, hi = numTris - 1;
    while (lo < hi) { const mid = (lo+hi) >> 1; if (cumArea[mid] < tgt) lo = mid+1; else hi = mid; }
    const b = lo * 9;

    // Barycentric coords via square-root method — independent sequences from triangle selector
    const sq = Math.sqrt((i * 0.381966) % 1.0);   // ≠ u above (different golden-ratio seq)
    const tv = (i * 0.754878) % 1.0;               // third independent low-discrepancy seq
    const ba = 1.0 - sq;
    const bb = sq * (1.0 - tv);
    const bc = sq * tv;  // ba+bb+bc = 1 ✓

    out[i*3]   = (ba*tris[b]  +bb*tris[b+3]+bc*tris[b+6] - ocx) * sc;
    out[i*3+1] = (ba*tris[b+1]+bb*tris[b+4]+bc*tris[b+7] - ocy) * sc;
    out[i*3+2] = (ba*tris[b+2]+bb*tris[b+5]+bc*tris[b+8] - ocz) * sc;
  }
}

function flipLine(lines, line) {
    if (line < 1 || line > 6)
        throw new Error('Line must be 1–6');
    const next = [...lines];
    next[line - 1] = next[line - 1] === 1 ? 0 : 1;
    return next;
}

function linesToBinary(lines) {
    return lines.reduce((value, line, index) => value | (line << index), 0);
}

function binaryToLines(value) {
    return Array.from({ length: 6 }, (_, index) => (value >> index) & 1);
}

function random(state) {
    let x = state.rngState | 0;
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    state.rngState = x >>> 0;
    return state.rngState / 4294967296;
}

function contourFor(memberIds, nodes) {
    const points = nodes.filter((node) => memberIds.includes(node.id)).map(({ x, y }) => ({ x, y })).sort((a, b) => a.x - b.x || a.y - b.y);
    if (points.length <= 2)
        return points;
    const cross = (o, a, b) => (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
    const lower = [];
    for (const point of points) {
        while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], point) <= 0)
            lower.pop();
        lower.push(point);
    }
    const upper = [];
    for (const point of [...points].reverse()) {
        while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], point) <= 0)
            upper.pop();
        upper.push(point);
    }
    return [...lower.slice(0, -1), ...upper.slice(0, -1)];
}

function connectionFor(state, source, target, dimension) {
    // r1.2: connections exist only between contributing fields. Space is the
    // resulting condition of their interaction (deriveSpace) and must never
    // become an independent connection carrier — fail loud, never silently.
    if (dimension === 'Space')
        throw new Error('Space is derived; it cannot carry a connection');
    const id = `${source}→${target}:${dimension}`;
    let connection = state.connections.find((item) => item.id === id);
    if (!connection) {
        connection = { id, source, target, dimension, weight: 0.08, uses: 0, inactiveTicks: 0, perturbationResponse: 0, sourceKind: 'event', context: 'created by realized interaction; reverse direction independent', history: [] };
        state.connections.push(connection);
    }
    return connection;
}

function perturbState(state, nodeId) {
    const next = structuredClone(state);
    const amount = next.parameters.perturbation;
    for (const connection of next.connections.filter((item) => item.source === nodeId || item.target === nodeId)) {
        const before = connection.weight;
        const direction = connection.source === nodeId ? 1 : -1;
        connection.weight = Math.max(0, Math.min(1, connection.weight + amount * direction));
        connection.perturbationResponse = connection.weight - before;
        connection.history.push({ tick: next.tick, eventId: `perturb-${next.tick}-${nodeId}`, before, after: connection.weight, cause: 'perturbation' });
    }
    return next;
}

function stateHash(state) {
    const canonical = JSON.stringify({ ...state, running: false });
    let hash = 2166136261;
    for (let index = 0; index < canonical.length; index += 1) {
        hash ^= canonical.charCodeAt(index);
        hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, '0');
}

function bounded(value, size, label) {
    if (!Number.isInteger(value) || value < 1 || value > size)
        throw new Error(`${label} must be an integer from 1 to ${size}`);
