}

function roleForMoment(need, nodeIndex) {
    switch (need) {
        case 'construct': return 'constructor';
        case 'organize': return 'organizer';
        case 'learn': return 'learner';
        case 'observe': {
            const cycle = ['ingestor', 'analyzer', 'recorder', 'addresser'];
            return cycle[nodeIndex % cycle.length];
        }
    }
}

function governingDimensionOf(state, formation) {
    const members = new Set(formation.memberIds);
    const counts = new Map();
    for (const event of state.events) {
        if (members.has(event.source) && members.has(event.target)) {
            counts.set(event.dimension, (counts.get(event.dimension) ?? 0) + 1);
        }
    }
    let best = null;
    let bestCount = 0;
    let tied = false;
    for (const [dim, count] of counts) {
        if (count > bestCount) {
            best = dim;
            bestCount = count;
            tied = false;
        }
        else if (count === bestCount)
            tied = true;
    }
    return best === null || tied ? 'unresolved' : best;
}

function agreementOf(node, governing) {
    if (governing === 'unresolved')
        return 'unresolved';
    const bases = ['Movement', 'Evolution', 'Being', 'Design'];
    const leading = bases.reduce((a, b) => (node.configurations[a].charge >= node.configurations[b].charge ? a : b));
    return leading === governing ? 'concord' : 'discord';
}

