function step(swarm, dt = 1, time = 0) {
  const { cx, cy, r } = swarm.center;
  const act = swarm.inner.filter(u => !u.latent);
  const mx = act.reduce((s, u) => s + u.x, 0) / (act.length || 1), my = act.reduce((s, u) => s + u.y, 0) / (act.length || 1);
  for (const u of swarm.inner) {
    let fx = (u.home.x - u.x) * 0.02, fy = (u.home.y - u.y) * 0.02; // tether to its address
    const e = Math.min(1.5, u.energy) * r * 0.0009;
    const dx = u.x - cx, dy = u.y - cy, d = Math.hypot(dx, dy) || 1;
    switch (u.dimension) {
      case 'Movement': fy -= e * 6; break;
      case 'Being': fx -= dx / d * e * 6; fy -= dy / d * e * 6; break;
      case 'Evolution': fx += dx / d * e * 6; fy += dy / d * e * 6; break;
      case 'Design': fx += -dy / d * e * 6; fy += dx / d * e * 6; break;
      case 'Space': fx += (mx - u.x) * 0.004 * u.energy; fy += (my - u.y) * 0.004 * u.energy; break;
      default: { const p = Math.sin(time * 0.002 + u.gate * 1.7 + u.line); fx += dx / d * p * 0.05; fy += dy / d * p * 0.05; }
    }
    u.vx = (u.vx + fx * dt) * 0.88; u.vy = (u.vy + fy * dt) * 0.88;
    u.x += u.vx * dt; u.y += u.vy * dt;
  }
  return swarm;
}

function blockFrom(text, start) { // body until braces balance (good enough for JS/CSS)
  const open = text.indexOf('{', start); if (open < 0) return text.slice(start, start + 200);
  let d = 0; for (let i = open; i < text.length; i++) { if (text[i] === '{') d++; else if (text[i] === '}' && --d === 0) return text.slice(start, i + 1); }
  return text.slice(start);
}

function resolve(from, spec, paths) {
  if (!spec || /^(https?:|data:|\/\/)/.test(spec)) return null;
  if (/^[@~]\//.test(spec)) { // project alias like @/components/x -> any file ending in components/x(.ext)
    const rest = spec.slice(2);
    for (const p of paths) for (const e of ['', '.ts', '.tsx', '.js', '.jsx', '.mjs', '/index.ts', '/index.tsx', '/index.js'])
      if (p === rest + e || p.endsWith('/' + rest + e) || p.endsWith('/' + rest.split('/').pop() + e) && rest.split('/').length === 1) return p;
    const leaf = rest.split('/').pop();
    for (const p of paths) if (p.replace(/\.\w+$/, '').split('/').pop() === leaf) return p;
    return null; }
  const dir = from.split('/').slice(0, -1);
  const parts = spec.startsWith('/') ? spec.slice(1).split('/') : [...dir, ...spec.split('/')];
  const stack = []; for (const p of parts) { if (p === '..') stack.pop(); else if (p && p !== '.') stack.push(p); }
  const base = stack.join('/');
  for (const c of [base, ...['.js', '.mjs', '.ts', '.tsx', '.jsx', '.json', '.css', '.py'].map(e => base + e), base + '/index.js', base + '/index.ts', base + '/index.tsx', base.replace(/\./g, '/') + '.py'])
    if (paths.has(c)) return c;
  // bare python module "pkg.mod" -> pkg/mod.py anywhere
  const tail = spec.replace(/\./g, '/') + '.py'; for (const p of paths) if (p.endsWith(tail)) return p;
  return null;
}

function proposals(s, ch = channels(s)) {
  const say = { module: h => h.half === 'in' ? `"${h.key}" is imported in ${h.file} but no file exports it` : `${h.file} exports "${h.key}" but nothing imports it`,
    wire: h => h.half === 'in' ? `${h.file} looks for #${h.key} but no markup has that id` : `#${h.key} in ${h.file} is never wired to a script`,
    style: h => h.half === 'in' ? `${h.file} uses ${h.key} but no stylesheet defines it` : `${h.key} is styled in ${h.file} but nothing uses it`,
    file: h => `${h.file} references ${h.key} but that file is missing`, call: h => `${h.file} calls ${h.key}, which is missing` };
  return ch.hanging.map(h => ({ gate: h, text: say[h.kind](h), severity: h.half === 'in' ? 'missing' : 'unused' }))
    .sort((a, b) => (a.severity === 'missing' ? 0 : 1) - (b.severity === 'missing' ? 0 : 1));
}

function learnImageField(width,height,pixels,{clusters=8,iterations=16}={}){
 if(!Number.isInteger(width)||!Number.isInteger(height)||width<1||height<1||width*height>4096||pixels.length!==width*height*4)throw Error('Image field requires at most 4096 RGBA samples');
 const count=width*height,k=Math.min(clusters,count),features=Array.from({length:count},(_,i)=>[pixels[i*4]/255,pixels[i*4+1]/255,pixels[i*4+2]/255,(i%width)/Math.max(1,width-1)*.45,Math.floor(i/width)/Math.max(1,height-1)*.45]);
 const centers=Array.from({length:k},(_,i)=>[...features[Math.min(count-1,Math.floor((i+.5)*count/k))]]),labels=new Uint8Array(count);let firstLoss=0,lastLoss=0;
 for(let step=0;step<iterations;step++){const sums=Array.from({length:k},()=>[0,0,0,0,0]),sizes=new Array(k).fill(0);let loss=0;for(let i=0;i<count;i++){let best=Infinity,which=0;for(let c=0;c<k;c++){const distance=features[i].reduce((a,v,j)=>a+(v-centers[c][j])**2,0);if(distance<best){best=distance;which=c;}}labels[i]=which;loss+=best;sizes[which]++;features[i].forEach((v,j)=>sums[which][j]+=v);}for(let c=0;c<k;c++)if(sizes[c])centers[c]=sums[c].map(v=>v/sizes[c]);if(step===0)firstLoss=loss/count;lastLoss=loss/count;}
 const samples=features.map((f,i)=>({id:'pixel.'+i,position:[((i%width)/Math.max(1,width-1)-.5)*4,(.5-Math.floor(i/width)/Math.max(1,height-1))*4*height/width,0],rgb:f.slice(0,3),alpha:pixels[i*4+3]/255,cluster:labels[i]}));const contacts=new Map();for(let y=0;y<height;y++)for(let x=0;x<width;x++){const i=y*width+x;for(const j of [x+1<width?i+1:-1,y+1<height?i+width:-1]){if(j<0||labels[i]===labels[j])continue;const pair=[labels[i],labels[j]].sort((a,b)=>a-b).join(':');contacts.set(pair,(contacts.get(pair)||0)+1);}}
 return {width,height,samples,centers,contacts:[...contacts].map(([key,boundary])=>({clusters:key.split(':').map(Number),boundary})),metrics:{method:'k-means/RGB+XY',iterations,examples:count,before:firstLoss,after:lastLoss,semantics:false,depth:false}};
}

function attachKleinObserver(swarm, interpret) {
 if (!swarm?.core?.onChange || !swarm?.core?.record || typeof interpret !== 'function')
   throw new TypeError('Dynamic Swarm substrate and original interpreter required');
 const observations=[];
 let active=true, busy=false;
 const stop=swarm.core.onChange(event=>{
  if (!active || busy || !['entity.changed','relation.created','signal.delivered','observation.recorded','gate.changed'].includes(event.type)) return;
  // Observe committed events, not imagined external decisions.
  // Ignore self-generated audit events to avoid recursion.
  if (event.type==='observation.recorded' && event.data?.kind==='klein-world-reading') return;
  const input={
   schema:'dynamic-swarm/klein-observation/v1',
   context_id:'swarm-event:'+event.seq,
   source_tool:'Codex3/Substrate.record',
   event:structuredClone(event),
   world:{entities:[...swarm.core.entities.values()].map(e=>({
    id:e.id,dimension:e.dimension,address:structuredClone(e.address),
    state:structuredClone(e.state)})),
    relations:[...swarm.core.relations.values()].map(r=>structuredClone(r))}
  };
  busy=true;
  try {
   const reading=interpret(input);
   // No fake inference, no async promise, no world mutation from the interpreter.
   if (reading && typeof reading.then!=='function' &&
       reading.context_id===input.context_id && typeof reading.source_tool==='string' &&
       reading.source_tool && Array.isArray(reading.relations)) {
    const audit={kind:'klein-world-reading',sourceEvent:event.seq,
      context_id:reading.context_id,source_tool:reading.source_tool,
      relations:structuredClone(reading.relations),
      reading:structuredClone(reading)};
    swarm.core.record('observation.recorded',audit);
    observations.push({seq:event.seq,status:'recorded',source_tool:reading.source_tool});
   } else observations.push({seq:event.seq,status:'unresolved'});
  } catch (error) {
   observations.push({seq:event.seq,status:'error',message:String(error).slice(0,160)});
  } finally {busy=false;if(observations.length>256)observations.shift();}
 });
 return {observations,detach(){active=false;stop();}};
}

function encodeBits(agents,order){
 if(!Array.isArray(order)||order.length!==8||new Set(order).size!==8)throw Error('ASCII groups need eight distinct particle identities');
 const byId=new Map(agents.map(a=>[a.id,a]));
 const bits=order.map(id=>{if(!byId.has(id))throw Error('ASCII group contains an unavailable particle');return byId.get(id).state.open===false?0:1;});
